using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad]public static class FinalLevelAuditV08 {
 const string Key="ZTM_FINAL_LEVEL_V08";static GameView view;static RenderTexture target;static int phase,warm,checks,buys,stories,frame0,lastFrame;static double start,last,phaseAt;static PlayerState complete;static readonly List<double> intervals=new List<double>();static readonly StringBuilder report=new StringBuilder();
 static string Root=>Directory.GetParent(Application.dataPath).FullName;static string SaveDir=>Path.Combine(Root,".tooling","v08-final-full-level-2","save");static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;
 static FinalLevelAuditV08(){EditorApplication.update+=Tick;}
 public static void BatchStart(){SessionState.SetBool(Key+"batch",true);Start();}
  public static string Start(){if(EditorApplication.isPlaying)throw new Exception("Own Editor playing");if(Directory.Exists(SaveDir))throw new Exception("Use immutable fresh final profile");view=null;phase=warm=checks=buys=stories=0;start=last=0;intervals.Clear();report.Clear();Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",SaveDir);UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();return "queued fresh actual level; no fixture setter";}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 static bool Same(PlayerState a,PlayerState b){if(a.cash!=b.cash||a.spins!=b.spins||a.freeSpins!=b.freeSpins||a.recoveries!=b.recoveries)return false;for(int i=0;i<8;i++)if(a.fragments[i]!=b.fragments[i]||a.purchased[i]!=b.purchased[i])return false;for(int i=0;i<15;i++)if(a.lastGrid[i]!=b.lastGrid[i])return false;return true;}
 static PlayerState Disk(){string notice;return new SaveStore(Path.Combine(SaveDir,"level1-v1.json"),new UnityStateCodec()).Load(out notice);}
 static void Capture(string name){var old=RenderTexture.active;RenderTexture.active=target;var t=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,target.width,target.height),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Root,"Evidence","final-v08-2-level-"+name+".png"),t.EncodeToPNG());UnityEngine.Object.Destroy(t);RenderTexture.active=old;}
 static void Attach(){view.GetComponent<UIDocument>().panelSettings.targetTexture=target;warm=0;}
 static void Reload(int nextPhase){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;view=null;warm=0;phase=nextPhase;phaseAt=EditorApplication.timeSinceStartup;SceneManager.LoadScene("Level1");}
 static void At(int p){phase=p;warm=0;phaseAt=EditorApplication.timeSinceStartup;}
 static bool Busy=>view.QaSpinning||UI.Q<VisualElement>("reward-to-task").resolvedStyle.display==DisplayStyle.Flex||((PixelEffects)typeof(GameView).GetField("effects",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(view)).PresentationBusy;
 static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying)return;try{if(start==0)start=EditorApplication.timeSinceStartup;if(EditorApplication.timeSinceStartup-start>360)throw new Exception("full-level timeout");if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;if(target==null){target=new RenderTexture(360,640,0,RenderTextureFormat.ARGB32);target.Create();frame0=Time.frameCount;lastFrame=Time.frameCount;last=Time.realtimeSinceStartupAsDouble;}Attach();}
 double now=Time.realtimeSinceStartupAsDouble;if(Time.frameCount!=lastFrame){if(phase>=2)intervals.Add((now-last)*1000);last=now;lastFrame=Time.frameCount;}Check(RoomGeometry.IsFree(view.QaFeet),"continuous feet clear of obstacles");if(++warm<30||EditorApplication.timeSinceStartup-phaseAt<.25)return;
 if(phase==0){var s=view.Model.Snapshot;Check(s.cash==0&&s.freeSpins==3&&s.spins==0&&view.Model.PurchasedCount==0,"real fresh load has zero cash and three free spins");Capture("fresh-360x640");view.QaClick("tutorial-skip");Check(Same(s,view.Model.Snapshot)&&view.Model.Snapshot.tutorial.skipped,"explicit intro skip changes no resources");phase=2;}
 else if(phase==2){if(Busy)return;var bubble=UI.Q<VisualElement>("heroine-dialogue");if(bubble.resolvedStyle.display==DisplayStyle.Flex){var before=view.Model.Snapshot;view.QaClick("tutorial-next");Check(Same(before,view.Model.Snapshot),"story dismissal changes no resources");stories++;return;}if(TutorialPolicy.PendingStory(view.Model.Snapshot)>=0)return;
 if(view.Model.Complete){complete=view.Model.Snapshot;Check(buys==8&&complete.spins>=40&&complete.spins<=100,"whole slow level reached via actual spin/purchase callbacks");Check(complete.tutorial.storySeenMask==15&&stories>=4,"all milestone comments explicitly dismissed");Check(Same(complete,Disk()),"complete room cash fragments grid survive disk reload");Capture("complete-360x640");File.WriteAllText(Path.Combine(Root,"Evidence","final-v08-2-level-completed-state.json"),JsonUtility.ToJson(complete,true));view.QaClick("menu");var before=view.Model.Snapshot;view.QaClick("motion-toggle");Check(PixelUi.ReducedMotion&&Same(before,view.Model.Snapshot),"calm preference set independently of game resources");view.QaClick("close-settings");Reload(3);return;}
 int q=view.Model.ActiveQuest;if(view.Model.CanBuy(q)){var before=view.Model.Snapshot;var d=view.Model.Definition(q);view.QaClick("buy-"+q);view.QaBuy(q);for(int i=0;i<20;i++)view.QaBuy(q);var after=view.Model.Snapshot;Check(view.Model.PurchasedCount==buys+1&&after.cash==before.cash-d.CashPrice&&after.fragments[q]==before.fragments[q]-d.FragmentGoal,"explicit manual purchase debit once");Check(Same(after,Disk()),"each installed upgrade/resources persist");buys++;report.AppendLine("PURCHASE "+buys+" spins="+after.spins+" cash="+after.cash);phase=21;warm=0;}
 else if(view.Model.CanSpin){var before=view.Model.Snapshot;view.QaClick("spin");var after=view.Model.Snapshot;if(after.spins==before.spins)return;Check(after.spins==before.spins+1,"single callback commits exactly one spin");int coins=0,triples=0,parts=0;foreach(int symbol in after.lastGrid){if(symbol==0)coins++;else{Check(symbol==q+1,"only cash and current matching symbols rendered");parts++;}}for(int x=0;x<5;x++)if(after.lastGrid[x]==after.lastGrid[x+5]&&after.lastGrid[x]==after.lastGrid[x+10])triples++;int cost=before.freeSpins>0?0:5;Check(after.cash==before.cash-cost+12+2*coins+10*triples&&after.fragments[q]-before.fragments[q]==parts,"actual grid pays exact cash and matching collectible count");Check(after.freeSpins==before.freeSpins-(cost==0?1:0)&&after.cash>=0,"starter allowance and spend remain coherent");Check(Same(after,Disk()),"spin committed before cosmetic completion");}
 else if(view.Model.CanRecover){view.QaClick("recovery");Check(view.Model.Snapshot.freeSpins==1,"transparent free recovery avoids deadlock");}else throw new Exception("progression deadlock");}
 else if(phase==21){if(Busy)return;Capture("installed-"+buys+"-360x640");phase=2;}
 else if(phase==3){Check(view.Model.Complete&&Same(complete,view.Model.Snapshot),"actual SceneManager reload restores full level");Check(PixelUi.ReducedMotion&&new PresentationPreferences(SaveDir).ReducedMotion,"calm setting survives actual scene reload");Check(UI.Q<VisualElement>("heroine-dialogue").resolvedStyle.display==DisplayStyle.None,"dismissed final story stays dismissed");Capture("reloaded-complete-360x640");view.QaClick("spin");view.QaBuy(7);Check(Same(complete,view.Model.Snapshot),"completed level rejects late spin and duplicate final BUY");view.QaClick("menu");At(30);}
 else if(phase==30){view.QaClick("reset");At(31);}
 else if(phase==31){view.QaClick("keep-room");At(32);}
 else if(phase==32){Check(view.Model.Complete&&Same(complete,view.Model.Snapshot),"reset cancellation preserves complete room");view.QaClick("reset");At(33);}
 else if(phase==33){view.QaClick("confirm-reset");At(34);}
 else if(phase==34){Check(view.Model.PurchasedCount==0&&view.Model.Snapshot.cash==0&&view.Model.Snapshot.freeSpins==3,"confirmed reset creates fresh starter state");Reload(4);}
 else if(phase==4){Check(view.Model.PurchasedCount==0&&view.Model.Snapshot.cash==0&&view.Model.Snapshot.freeSpins==3&&view.Model.Snapshot.spins==0,"fresh reset survives actual reload");Check(TutorialPolicy.Step(view.Model.Snapshot)==0,"fresh introduction restored");Capture("reloaded-reset-360x640");report.AppendLine("PASS checks="+checks+" completeSpins="+complete.spins+" manualBuys="+buys+" storyDismissals="+stories+" runtimeFrames="+(Time.frameCount-frame0));Finish(true);}
 }catch(Exception e){report.AppendLine("FAIL "+e);Debug.LogException(e);Finish(false);}}
 [Serializable]sealed class Timing{public string scope;public int frames,samples;public double medianMs,p95Ms,maxMs,elapsedSeconds;}
 static void Finish(bool pass){SessionState.SetBool(Key,false);intervals.Sort();var timing=new Timing{scope="Owned Unity Editor offscreen actual frames; synthetic callbacks; includes screenshot pauses; not standalone/device benchmark",frames=Time.frameCount-frame0,samples=intervals.Count,elapsedSeconds=EditorApplication.timeSinceStartup-start};if(intervals.Count>0){timing.medianMs=intervals[intervals.Count/2];timing.p95Ms=intervals[(int)((intervals.Count-1)*.95)];timing.maxMs=intervals[intervals.Count-1];}File.WriteAllText(Path.Combine(Root,"Evidence","final-v08-2-level-editor-timing.json"),JsonUtility.ToJson(timing,true));report.AppendLine("RESULT "+(pass?"PASS":"FAIL")+"; fresh real load, no fixture setter; Editor actual offscreen render; UI callbacks synthetic; no OS/native input");File.WriteAllText(Path.Combine(Root,"Evidence","final-v08-2-level-checks.txt"),report.ToString());if(target!=null){if(view!=null)view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);target=null;}EditorApplication.ExitPlaymode();if(SessionState.GetBool(Key+"batch",false))EditorApplication.delayCall+=()=>EditorApplication.Exit(0);}
 }
}